entries[278413] = { ["name"] = "Monelitfischfinder", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nMoneliterz (30), Sturmsilbererz (5), Chemische Sprengkapsel (2), Isoliertes Kabel (8), Expulsom (10), Hydrokern\nStellt einen Monelitfischfinder her.\nBerufsausbilder:\nIngenieurskunst von Battle for Azeroth (50)\nKosten:\n2\n\nMonelitfischfinder\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with a Monelite Fish Finder which grants:Chance to bring back fish from successful missions." }
entries[278414] = { ["name"] = "Gischtvernebeltes Leinen mit Haken", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nGischtvernebeltes Leinen (75), Nylonfaden (20), Expulsom (30), Hydrokern\nStellt gischtvernebeltes Leinen mit Haken her.\nBerufsausbilder:\nSchneiderei von Battle for Azeroth (75)\nKosten:\n3\n50\n\nGischtvernebeltes Leinen mit Haken\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with Rough-hooked Tidespray Linen which grants:Chance to bring back cloth from successful missions." }
entries[278415] = { ["name"] = "Sturmsilbersporen", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nSturmsilbererz (35), Platinerz (5), Langlebiger Fluxus (20), Expulsom (20), Hydrokern\nStellt Sturmsilbersporen her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (65)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n75\n\nSturmsilbersporen\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with Storm Silver Spurs which grants:Equip a champion with Storm Silver Spurs which grants:Decreases mission duration by 20%." }
entries[278416] = { ["name"] = "Magnetische Spitzhacke", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nSturmsilbererz (40), Platinerz (10), Langlebiger Fluxus (20), Expulsom (15), Hydrokern\nStellt eine magnetische Spitzhacke her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (65)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n75\n\nMagnetische Spitzhacke\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with a Magnetic Mining Pick which grants:Chance to bring back ore from successful missions." }
entries[278417] = { ["name"] = "Platinwetzstein", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nPlatinerz (5), Expulsom (10), Hydrokern\nStellt einen Platinwetzstein her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (65)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n75\n\nPlatinwetzstein\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with a Platinum Whetstone which grants:Increases mission success chance by 10%." }
entries[278418] = { ["name"] = "Entzauberungsrute", ["text"] = "Wirken in 3 sek.\nReagenzien:\nSternenholz , Düsterstaub (40), Trüber Kristall (5), Expulsom (30), Hydrokern\nStellt eine Entzauberungsrute her.\nBeruf:\nVerzauberkunst von Battle for Azeroth (60)\nLehrer:\nVerzauberin Quinni\nZone:\nZuldazar\nKosten:\n2\n50\n\nEntzauberungsrute\nChampionausrüstung\nWird bei Benutzung gebunden\nBenutzen: Equip a champion with a Disenchanting Rod which grants:Chance to bring back enchanting dust from successful missions." }
